"""Lab tool `run_experiment` (generated by lab/build_bundle.py; do not edit)."""

from __future__ import annotations

import json

from omnigent_client.tools import tool

ACTOR = "statistician"


@tool
def run_experiment(experiment: str, params_json: str = "{}") -> str:
    """
    Run one registered experiment on frozen taxonomies. Costs credits; refused when the budget is spent.

    :param experiment: e.g. ``"tournament"``, ``"defectors"``, ``"tomb_test"``, ``"hindsight_gap"``, ``"corpus_map"``, ``"probe_score"``.
    :param params_json: JSON parameters, e.g. ``{"taxonomy_id": "T_six", "instrument": "lex"}``.
    :returns: JSON with record ids, credits left and the result summary.
    """
    from labtools import core

    return json.dumps(core.run_experiment(ACTOR, experiment, params_json), ensure_ascii=False)
